efault(false) // 👈 AJOUT\n  gradesGeneratedAt DateTime?\n  semester          semester       @relation(fields: [semesterId], references: [id])\n  subject           Cours[]        @relation(\"PeriodSubjects\")\n  grades            StudentGrade[]\n  branchId          String\n  branch            Branch         @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, semesterId, label])\n  @@index([semesterId], map: \"Period_semesterId_fkey\")\n  @@index([branchId])\n  @@index([branchId, semesterId])\n}\n\nmodel PeriodResultLock {\n  id        String   @id @default(cuid())\n  periodId  Int\n  status    String\n  createdAt DateTime @default(now())\n  updateAT  DateTime @default(now())\n  branchId  String\n  branch    Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([periodId])\n  @@unique([branchId, periodId])\n  @@index([branchId])\n}\n\nmodel fiche {\n  id             String   @id\n  dateCreated    DateTime @default(now())\n  dateUpdated    DateTime\n  status         Boolean  @default(false)\n  teacherId      String\n  typeFiche      String\n  classSectionId String\n  lessonId       String\n  coursName      String\n  classeName     String\n  periodId       Int\n  periodeName    String\n  anneeId        String\n  anneeName      String\n  notes          String   @db.Text\n  autres         String   @db.Text\n  ClassSection   Classe   @relation(fields: [classSectionId], references: [id], map: \"Fiche_Id_fkey\")\n  lesson         Teaching @relation(fields: [lessonId], references: [id])\n  period         period   @relation(fields: [periodId], references: [id])\n  teacher        Teacher  @relation(fields: [teacherId], references: [id], map: \"Fiche_teacherId_fkey\")\n  branchId       String\n  branch         Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([lessonId], map: \"Fiche_lessonId_fkey\")\n  @@index([periodId], map: \"Fiche_periodId_fkey\")\n  @@index([branchId])\n  @@index([branchId, anneeId])\n  @@index([branchId, periodId])\n  @@index([branchId, teacherId])\n}\n\nenum Recurrence {\n  JOURNALIER\n  HEBDOMADAIRE\n  MENSUEL\n  SEMESTRIEL\n  TRIMESTRIEL\n  ANNUEL\n}\n\nenum ActionType {\n  LOGIN\n  LOGOUT\n  VISITED_PAGE\n  ACTION\n}\n\nenum DeviceType {\n  MOBILE\n  DESKTOP\n  TABLET\n  OTHER\n}\n\n//////////////////////////////////////////////////////\n// INVOICES\n//////////////////////////////////////////////////////\n\nmodel Invoice {\n  id           Int    @id @default(autoincrement())\n  enrollmentId String\n  YearId       String\n\n  totalAmount Float\n  discount    Float  @default(0)\n  finalAmount Float\n  paidAmount  Float  @default(0)\n  branchId    String\n  branch      Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  status InvoiceStatus @default(UNPAID)\n\n  enrollment ClassEnrollment @relation(fields: [enrollmentId], references: [id])\n  schoolYear SchoolYear      @relation(fields: [YearId], references: [id])\n\n  allocations PaymentAllocation[]\n\n  @@unique([branchId, enrollmentId, YearId])\n  @@index([branchId])\n  @@index([branchId, YearId])\n}\n\n//////////////////////////////////////////////////////\n// PAYMENT BATCH (PAIEMENT GROUPÉ)\n//////////////////////////////////////////////////////\n\nmodel PaymentBatch {\n  id          Int             @id @default(autoincrement())\n  parentId    String\n  totalAmount Float\n  status      PaymentStatus   @default(EN_ATTENTE)\n  createdAt   DateTime        @default(now())\n  parent      Parent          @relation(fields: [parentId], references: [id])\n  payments    FamilyPayment[]\n  branchId    String\n  branch      Branch          @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([branchId])\n  @@index([branchId, parentId])\n}\n\n//////////////////////////////////////////////////////\n// PAYMENTS\n//////////////////////////////////////////////////////\n\nmodel FamilyPayment {\n  id                String                  @id @default(cuid())\n  parentId          String\n  batchId           Int?\n  /// Montant de reference metier (devise de base de l'organisation)\n  amount            Float\n  /// Devise reellement percue a la caisse\n  receivedCurrency  CurrencyCode            @default(USD)\n  /// Montant perçu dans receivedCurrency\n  receivedAmount    Float?\n  /// Taux applique au moment du paiement (audit)\n  exchangeRateUsed  Float?\n  method            PaymentMethod\n  transactionRef    String\n  notes             String?\n  status            PaymentStatus           @default(EN_ATTENTE)\n  createdAt         DateTime                @default(now())\n  updatedAt         DateTime                @default(now())\n  parent            Parent                  @relation(fields: [parentId], references: [id])\n  batch             PaymentBatch?           @relation(fields: [batchId], references: [id])\n  allocations       PaymentAllocation[]\n  mobileTx          MobileMoneyTransaction?\n  events            PaymentEvent[]\n  fraisId           String\n  frais             Frais?                  @relation(fields: [fraisId], references: [id], onDelete: Restrict)\n  classEnrollment   ClassEnrollment?        @relation(fields: [classEnrollmentId], references: [id], onDelete: Cascade)\n  classEnrollmentId String\n  branchId          String\n  branch            Branch                  @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, transactionRef])\n  @@index([fraisId])\n  @@index([classEnrollmentId])\n  @@index([transactionRef])\n  @@index([branchId])\n  @@index([branchId, parentId])\n  @@index([branchId, createdAt])\n  @@index([branchId, receivedCurrency])\n}\n\nmodel CashierExpense {\n  id             String   @id @default(cuid())\n  transactionRef String\n  amount         Float\n  description    String?\n  category       String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  branchId       String\n  branch         Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, transactionRef])\n  @@index([branchId])\n}\n\nmodel CashierOpeningBalance {\n  id        String   @id @default(cuid())\n  amount    Float\n  /// Jour civil du solde d'ouverture (minuit UTC localise cote app)\n  date      DateTime @db.Date\n  note      String?\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  branchId  String\n  branch    Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, date])\n  @@index([branchId, date])\n}\n\n/// Taux de change par organisation (partages par toutes les branches)\nmodel ExchangeRate {\n  id             String       @id @default(cuid())\n  fromCurrency   CurrencyCode\n  toCurrency     CurrencyCode\n  /// 1 unite fromCurrency = rate unites toCurrency\n  rate           Float\n  isActive       Boolean      @default(true)\n  /// Un seul taux selectionne par organisation : fromCurrency = devise de base\n  isSelected     Boolean      @default(false)\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  createdBy      String?\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  @@unique([organizationId, fromCurrency, toCurrency])\n  @@index([organizationId, isActive])\n  @@index([organizationId, isSelected])\n}\n\nmodel PaymentAllocation {\n  id              Int    @id @default(autoincrement())\n  familyPaymentId String\n  invoiceId       Int\n  amount          Float\n  branchId        String\n  branch          Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  familyPayment FamilyPayment @relation(fields: [familyPaymentId], references: [id])\n  invoice       Invoice       @relation(fields: [invoiceId], references: [id])\n\n  @@unique([familyPaymentId, invoiceId])\n  @@index([branchId])\n}\n\n//////////////////////////////////////////////////////\n// MOBILE MONEY\n//////////////////////////////////////////////////////\n\nmodel MobileMoneyTransaction {\n  id          Int           @id @default(autoincrement())\n  paymentId   String        @unique\n  provider    PaymentMethod\n  phoneNumber String\n  externalId  String        @unique\n  status      PaymentStatus\n  rawResponse String?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n  branchId    String\n  branch      Branch        @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  payment FamilyPayment @relation(fields: [paymentId], references: [id])\n\n  @@index([branchId])\n  @@index([branchId, externalId])\n}\n\n//////////////////////////////////////////////////////\n// LOGS / EVENTS\n//////////////////////////////////////////////////////\n\nmodel PaymentEvent {\n  id        Int           @id @default(autoincrement())\n  paymentId String\n  type      String\n  message   String?\n  createdAt DateTime      @default(now())\n  branchId  String\n  branch    Branch        @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  payment   FamilyPayment @relation(fields: [paymentId], references: [id])\n\n  @@index([branchId])\n  @@index([branchId, paymentId])\n}\n\n//////////////////////////////////////////////////////\n// DISCOUNTS\n//////////////////////////////////////////////////////\n\nenum DiscountScope {\n  PARENT\n  GROUP\n  ORPHAN\n}\n\nmodel DiscountRule {\n  id          Int              @id @default(autoincrement())\n  scope       DiscountScope // 🔥 PARENT / ORPHAN / GROUP\n  category    StudentCategory? // ORPHAN, VIP, etc (optionnel)\n  parentId    String? // si scope = PARENT\n  minChildren Int?\n  percentage  Float\n  /// Type de frais sur lequel la remise s'applique (inscription). Null = tous les frais (legacy).\n  typeFraisId String?\n  createdAt   DateTime         @default(now())\n  parent      Parent?          @relation(fields: [parentId], references: [id])\n  typeFrais   TypeFrais?       @relation(fields: [typeFraisId], references: [id], onDelete: SetNull)\n  branchId    String\n  branch      Branch           @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([branchId])\n  @@index([branchId, scope])\n  @@index([typeFraisId])\n}\n\nmodel Transaction {\n  id        String   @id @default(uuid())\n  reference String   @unique\n  updatedAt DateTime @default(now())\n  createdAt DateTime @default(now())\n  branchId  String\n  branch    Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([branchId])\n}\n\nenum ModePaiement {\n  ESPECES\n  CHEQUE\n  VIREMENT\n  MOBILE_MONEY\n  CARTE_BANCAIRE\n}\n\n//////////////////////////////////////////////////////\n// ENUMS\n//////////////////////////////////////////////////////\n\nenum PaymentMethod {\n  ESPECES\n  MPESA\n  AIRTEL_MONEY\n  ORANGE_MONEY\n  CARTE\n  BANQUE\n}\n\nenum CurrencyCode {\n  USD\n  CDF\n  AOA\n}\n\nenum PaymentStatus {\n  VALIDE\n  ANNULE\n  EN_ATTENTE\n  REMBOURSE\n}\n\nenum InvoiceStatus {\n  UNPAID\n  PARTIAL\n  PAID\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n}\n\nenum StudentCategory {\n  NORMAL\n  ORPHAN\n  VIP\n  SPONSORED\n  GROUPE\n}\n\nmodel Session {\n  id                   String   @id\n  expiresAt            DateTime\n  token                String\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n  ipAddress            String?\n  userAgent            String?\n  userId               String\n  user                 User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  impersonatedBy       String?\n  activeOrganizationId String?\n  activeBranchId       String?\n\n  @@unique([token])\n  @@index([userId])\n  @@index([activeOrganizationId])\n  @@index([activeBranchId])\n  @@index([userId, activeOrganizationId])\n  @@index([userId, activeBranchId])\n  @@index([expiresAt])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  @@unique([providerId, accountId])\n  @@index([userId])\n  @@index([providerId])\n  @@index([accountId])\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([identifier])\n  @@index([expiresAt])\n  @@map(\"verification\")\n}\n\nmodel Organization {\n  id                         String                      @id\n  name                       String\n  slug                       String\n  logo                       String?\n  createdAt                  DateTime\n  metadata                   String?\n  isArchived                 Boolean                     @default(false)\n  archivedAt                 DateTime?\n  archivedById               String?\n  organizationroles          OrganizationRole[]\n  members                    Member[]\n  branches                   Branch[]\n  invitations                Invitation[]\n  organizationSupportAgents  OrganizationSupportAgent[]\n  platformSupportEscalations PlatformSupportEscalation[]\n  exchangeRates              ExchangeRate[]\n\n  @@unique([name])\n  @@unique([slug])\n  @@index([isArchived])\n  @@map(\"organization\")\n}\n\nmodel OrganizationRole {\n  id             String       @id\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  role           String\n  permission     String\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime?    @updatedAt\n\n  @@unique([organizationId, role])\n  @@index([organizationId])\n  @@index([role])\n  @@map(\"organizationRole\")\n}\n\nmodel Member {\n  id                       String                    @id\n  organizationId           String\n  organization             Organization              @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  userId                   String\n  user                     User                      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role                     String                    @default(\"member\")\n  createdAt                DateTime\n  isArchived               Boolean                   @default(false)\n  archivedAt               DateTime?\n  archivedById             String?\n  branchMember             BranchMember[]\n  organizationSupportAgent OrganizationSupportAgent?\n\n  @@unique([organizationId, userId])\n  @@index([organizationId])\n  @@index([userId])\n  @@index([organizationId, role])\n  @@index([organizationId, isArchived])\n  @@map(\"member\")\n}\n\nmodel Invitation {\n  id             String       @id\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  email          String\n  role           String?\n  status         String       @default(\"pending\")\n  expiresAt      DateTime\n  createdAt      DateTime     @default(now())\n  inviterId      String\n  user           User         @relation(fields: [inviterId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId])\n  @@index([email])\n  @@index([organizationId, status])\n  @@index([expiresAt])\n  @@index([inviterId])\n  @@index([organizationId, email])\n  @@map(\"invitation\")\n}\n\nmodel Branch {\n  id               String       @id @default(cuid())\n  name             String\n  code             String?\n  image            Json?\n  /// Texte optionnel affiché à la une sur la page d'accueil (spotlight)\n  note             String?      @db.Text\n  adresse          String?\n  province         String?\n  ville            String?\n  commune          String?\n  pays             String?\n  idnat            String?\n  tel              String?\n  latitude         Float\n  longitude        Float\n  attendanceRadius Int          @default(100)\n  organizationId   String\n  typebranch       TypeBrache\n  organization     Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  isActive Boolean @default(true)\n\n  createdAt                       DateTime                         @default(now())\n  updatedAt                       DateTime                         @updatedAt\n  studentAttendance               StudentAttendance[]\n  branchemembers                  BranchMember[]\n  classes                         Classe[]\n  paymentBatch                    PaymentBatch[]\n  familyPayment                   FamilyPayment[]\n  fiche                           fiche[]\n  eventType                       EventType[]\n  period                          period[]\n  cours                           Cours[]\n  schoolYear                      SchoolYear[]\n  typeFrais                       TypeFrais[]\n  option                          Option[]\n  coursPonderations               CoursOptionPonderation[]\n  classEnrollment                 ClassEnrollment[]\n  section                         Section[]\n  semester                        semester[]\n  frais                           Frais[]\n  calendarEvent                   CalendarEvent[]\n  periodResultLock                PeriodResultLock[]\n  cashierExpense                  CashierExpense[]\n  cashierOpeningBalance           CashierOpeningBalance[]\n  invoice                         Invoice[]\n  creneau                         Creneau[]\n  paymentAllocation               PaymentAllocation[]\n  teaching                        Teaching[]\n  mobileMoneyTransaction          MobileMoneyTransaction[]\n  branchInvitation                BranchInvitation[]\n  attendanceSessions              AttendanceSession[]\n  teacherAttendance               TeacherAttendance[]\n  personnelAttendance             PersonnelAttendance[]\n  studentGrade                    StudentGrade[]\n  parentFeedback                  ParentFeedback[]\n  transaction                     Transaction[]\n  discountRule                    DiscountRule[]\n  paymentEvent                    PaymentEvent[]\n  partnaires                      Partnaire[]\n  organizationSupportBranchScopes OrganizationSupportBranchScope[]\n  registrationRequests            RegistrationRequest[]\n  registrationInfos               BranchRegistrationInfo[]\n  jobApplications                 JobApplication[]\n  targetStudentLinks              StudentBranchLink[]              @relation(\"TargetBranchLinks\")\n  sourceStudentLinks              StudentBranchLink[]              @relation(\"SourceBranchLinks\")\n  issuedDocuments                 IssuedDocument[]\n  libraryBooks                    LibraryBook[]\n\n  @@unique([organizationId, code])\n  @@index([organizationId])\n  @@index([organizationId, isActive])\n  @@index([organizationId, typebranch])\n  @@index([code])\n}\n\n/// Infos publiques d'inscription en ligne (conditions, frais, programme rentrée), par école / année.\nmodel BranchRegistrationInfo {\n  id           String  @id @default(cuid())\n  branchId     String\n  schoolYearId String?\n  isPublished  Boolean @default(false)\n\n  termsTitle   String @default(\"Conditions d'inscription\")\n  termsContent String @db.Text\n\n  registrationFeeRequired Boolean  @default(true)\n  registrationFeeAmount   Decimal? @db.Decimal(12, 2)\n  registrationFeeCurrency String   @default(\"CDF\")\n  registrationFeeLabel    String?\n  registrationFeeDueNote  String?\n  registrationFeeTypeId   String?\n\n  /// [{ \"date\": \"2026-09-01\", \"title\": \"...\", \"description\": \"...\" }, ...]\n  rentreeProgram Json?\n\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  branch     Branch      @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  schoolYear SchoolYear? @relation(fields: [schoolYearId], references: [id], onDelete: SetNull)\n\n  @@unique([branchId, schoolYearId])\n  @@index([branchId, isPublished])\n  @@index([schoolYearId])\n}\n\nmodel RegistrationRequest {\n  id               String                    @id @default(cuid())\n  reference        String                    @unique\n  branchId         String\n  organizationId   String\n  schoolYearId     String?\n  status           RegistrationRequestStatus @default(PENDING)\n  studentData      Json\n  guardiansData    Json\n  requestedLevel   String?\n  requestedSection String?\n  requestedOption  String?\n  photoUrl         String?\n  consentAccepted  Boolean                   @default(false)\n  termsAcceptedAt  DateTime?\n  termsInfoId      String?\n  confirmedById    String?\n  confirmedAt      DateTime?\n  registeredById   String?\n  registeredAt     DateTime?\n  studentId        String?\n  rejectedReason   String?\n  createdAt        DateTime                  @default(now())\n  updatedAt        DateTime                  @updatedAt\n  branch           Branch                    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([branchId, status, createdAt])\n  @@index([organizationId, branchId])\n  @@index([schoolYearId])\n  @@index([studentId])\n}\n\nenum RegistrationRequestStatus {\n  PENDING\n  CONFIRMED\n  REJECTED\n  CANCELLED\n  REGISTERED\n  ARCHIVED\n}\n\nenum JobApplicationType {\n  TEACHER\n  PERSONNEL\n}\n\nenum JobApplicationStatus {\n  PENDING\n  REVIEWED\n  ACCEPTED\n  REJECTED\n  HIRED\n  CANCELLED\n}\n\nmodel JobApplication {\n  id              String               @id @default(cuid())\n  reference       String               @unique\n  branchId        String\n  organizationId  String\n  applicationType JobApplicationType\n  status          JobApplicationStatus @default(PENDING)\n\n  nom         String\n  postnom     String\n  prenom      String\n  sexe        String\n  dateOfBirth DateTime\n  telephone   String\n  email       String\n  address     String\n  photoUrl    String?\n\n  desiredSubjects   String?\n  desiredLevels     String?\n  yearsOfExperience Int?\n  desiredOrgRole    String?\n\n  experienceSummary String? @db.Text\n  educationSummary  String? @db.Text\n  skills            String? @db.Text\n  availability      String?\n  motivation        String? @db.Text\n\n  cvUrl          String\n  coverLetterUrl String\n\n  consentAccepted Boolean @default(false)\n\n  reviewedById   String?\n  reviewedAt     DateTime?\n  acceptedById   String?\n  acceptedAt     DateTime?\n  rejectedReason String?\n  hiredById      String?\n  hiredAt        DateTime?\n  teacherId      String?\n  personnelId    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  branch    Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@index([branchId, status, createdAt])\n  @@index([organizationId, branchId])\n  @@index([email])\n  @@index([applicationType])\n}\n\nmodel Partnaire {\n  id            String    @id @default(cuid())\n  name          String\n  slug          String?\n  type          String?\n  secteur       String?\n  description   String?   @db.Text\n  image         String\n  tel           String\n  email         String?\n  website       String?\n  adresse       String?\n  ville         String?\n  pays          String?\n  contactName   String?\n  contactRole   String?\n  logo          String?\n  documentUrl   String?\n  contractRef   String?\n  contractStart DateTime?\n  contractEnd   DateTime?\n  isActive      Boolean   @default(true)\n  isFeatured    Boolean   @default(false)\n  notes         String?   @db.Text\n  branchId      String?\n  branch        Branch?   @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([slug])\n  @@index([branchId])\n  @@index([isActive])\n  @@index([isFeatured])\n  @@index([ville])\n  @@index([pays])\n}\n\nmodel BranchMember {\n  id String @id @default(cuid())\n\n  branchId String\n  memberId String\n  role     BranchRole\n  teacher  Teacher[]\n  parent   Parent[]\n  schedule Schedule[]\n  personel Personnel[]\n  student  Student[]\n  branch   Branch      @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  member   Member      @relation(fields: [memberId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([branchId, memberId])\n  @@index([branchId])\n  @@index([memberId])\n  @@index([branchId, role])\n  @@index([memberId, role])\n}\n\nenum BranchRole {\n  DIRECTOR\n  CAISSIER\n  ADMIN\n  TEACHER\n  PARENT\n  STUDENT\n}\n\nenum TypeBrache {\n  PRIMAIRE\n  SECONDAIRE\n  ATELIER\n  CENTRE_FORMATION\n  UNIVERSITE\n}\n\nenum StudentLinkType {\n  IMPORTED\n  NATIVE\n}\n\nenum IssuedDocumentType {\n  BULLETIN\n  BREVET\n  RELEVE_NOTES\n  ATTESTATION\n  ATTESTATION_PARTICIPATION\n}\n\nmodel StudentBranchLink {\n  id             String          @id @default(cuid())\n  studentId      String\n  targetBranchId String\n  sourceBranchId String\n  linkType       StudentLinkType @default(IMPORTED)\n  isActive       Boolean         @default(true)\n  enrolledAt     DateTime        @default(now())\n  endedAt        DateTime?\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  student      Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  targetBranch Branch  @relation(\"TargetBranchLinks\", fields: [targetBranchId], references: [id], onDelete: Cascade)\n  sourceBranch Branch  @relation(\"SourceBranchLinks\", fields: [sourceBranchId], references: [id], onDelete: Cascade)\n\n  @@unique([studentId, targetBranchId])\n  @@index([targetBranchId])\n  @@index([sourceBranchId])\n  @@index([studentId])\n  @@index([targetBranchId, isActive])\n}\n\nmodel IssuedDocument {\n  id           String             @id @default(cuid())\n  branchId     String\n  studentId    String\n  schoolYearId String?\n  documentType IssuedDocumentType\n  title        String\n  metadata     Json?\n  issuedAt     DateTime           @default(now())\n  issuedById   String?\n  pdfUrl       String?\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  branch     Branch      @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  student    Student     @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  schoolYear SchoolYear? @relation(fields: [schoolYearId], references: [id], onDelete: SetNull)\n\n  @@index([branchId, documentType])\n  @@index([studentId])\n  @@index([branchId, studentId])\n  @@index([schoolYearId])\n}\n\n/// Domaines du bulletin primaire RDC\nenum PrimaryDomain {\n  LANGUES\n  MATH_SCIENCES_TECH\n  UNIVERS_SOCIAUX\n  ARTS\n  DEVELOPPEMENT\n}\n\nmodel BranchInvitation {\n  id String @id @default(cuid())\n\n  email    String\n  branchId String\n\n  role  BranchRole\n  token String     @unique\n\n  expiresAt DateTime\n  accepted  Boolean  @default(false)\n\n  createdAt DateTime @default(now())\n\n  branch Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, email])\n  @@index([branchId])\n  @@index([email])\n}\n\n// ─── Bibliothèque scolaire (PDF/EPUB, lecture seule élèves) ───────────────────\n\nenum LibraryCycle {\n  PRIMAIRE\n  SECONDAIRE\n  HUMANITES\n  FORMATION\n  UNIVERSITE\n}\n\nenum LibraryFileType {\n  PDF\n  EPUB\n}\n\nenum LibraryVisibility {\n  STUDENTS\n}\n\nenum LibrarySource {\n  SCHOOL_UPLOAD\n  OPEN_LICENSE\n  PLATFORM_CATALOG\n}\n\nmodel LibraryBook {\n  id          String  @id @default(cuid())\n  title       String\n  author      String?\n  publisher   String?\n  description String? @db.Text\n  coverImage  String?\n\n  /// Chemin stockage privé côté serveur (jamais exposé au client)\n  fileUrl   String\n  fileType  LibraryFileType\n  fileSize  Int?\n  pageCount Int?\n  language  String          @default(\"fr\")\n  license   String?\n  isbn      String?\n\n  cycle    LibraryCycle?\n  level    String?\n  section  String?\n  subject  String?\n  category String?\n  tags     String[]      @default([])\n\n  visibility    LibraryVisibility @default(STUDENTS)\n  allowDownload Boolean           @default(false)\n  isActive      Boolean           @default(true)\n  source        LibrarySource     @default(SCHOOL_UPLOAD)\n  sortOrder     Int               @default(0)\n  viewCount     Int               @default(0)\n\n  branchId String\n  branch   Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?\n\n  @@index([branchId])\n  @@index([branchId, isActive])\n  @@index([cycle])\n  @@index([level])\n  @@index([subject])\n  @@index([category])\n  @@index([visibility])\n  @@index([fileType])\n}\n\n// ─── Support plateforme (équipe Klambocore) ───────────────────────────────────\n\nmodel PlatformSupportAgent {\n  id                  String                      @id @default(cuid())\n  userId              String                      @unique\n  user                User                        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  displayTitle        String?\n  bio                 String?                     @db.Text\n  specialties         String[]                    @default([])\n  image               String?\n  isActive            Boolean                     @default(true)\n  isLead              Boolean                     @default(false)\n  sortOrder           Int                         @default(0)\n  createdAt           DateTime                    @default(now())\n  updatedAt           DateTime                    @updatedAt\n  assignedEscalations PlatformSupportEscalation[]\n\n  @@index([isActive])\n  @@index([sortOrder])\n  @@map(\"platformSupportAgent\")\n}\n\n// ─── Support organisation (agents internes à une école) ─────────────────────\n\nmodel OrganizationSupportAgent {\n  id             String                           @id @default(cuid())\n  memberId       String                           @unique\n  member         Member                           @relation(fields: [memberId], references: [id], onDelete: Cascade)\n  organizationId String\n  organization   Organization                     @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  displayTitle   String?\n  bio            String?                          @db.Text\n  specialties    String[]                         @default([])\n  isActive       Boolean                          @default(true)\n  isPrimary      Boolean                          @default(false)\n  createdAt      DateTime                         @default(now())\n  updatedAt      DateTime                         @updatedAt\n  branchScopes   OrganizationSupportBranchScope[]\n  escalations    PlatformSupportEscalation[]\n\n  @@index([organizationId])\n  @@index([organizationId, isActive])\n  @@map(\"organizationSupportAgent\")\n}\n\nmodel OrganizationSupportBranchScope {\n  id        String                   @id @default(cuid())\n  supportId String\n  support   OrganizationSupportAgent @relation(fields: [supportId], references: [id], onDelete: Cascade)\n  branchId  String?\n  branch    Branch?                  @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([supportId, branchId])\n  @@index([supportId])\n  @@index([branchId])\n  @@map(\"organizationSupportBranchScope\")\n}\n\nenum PlatformSupportEscalationStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\n// Demande d'escalade : un support organisation contacte l'équipe Klambocore\nmodel PlatformSupportEscalation {\n  id                      String                          @id @default(cuid())\n  organizationId          String\n  organization            Organization                    @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  organizationSupportId   String?\n  organizationSupport     OrganizationSupportAgent?       @relation(fields: [organizationSupportId], references: [id], onDelete: SetNull)\n  requesterUserId         String\n  requesterUser           User                            @relation(\"EscalationRequester\", fields: [requesterUserId], references: [id], onDelete: Cascade)\n  assignedPlatformAgentId String?\n  assignedPlatformAgent   PlatformSupportAgent?           @relation(fields: [assignedPlatformAgentId], references: [id], onDelete: SetNull)\n  subject                 String\n  message                 String                          @db.Text\n  status                  PlatformSupportEscalationStatus @default(OPEN)\n  priority                String                          @default(\"normal\")\n  createdAt               DateTime                        @default(now())\n  updatedAt               DateTime                        @updatedAt\n  resolvedAt              DateTime?\n\n  @@index([organizationId])\n  @@index([requesterUserId])\n  @@index([status])\n  @@index([assignedPlatformAgentId])\n  @@map(\"platformSupportEscalation\")\n}\n",
